/bin/bash -lc "bash -lc '
set -euo pipefail

clickhouse-client --multiquery <<\"SQL\"
CREATE DATABASE IF NOT EXISTS analytics;
DROP TABLE IF EXISTS analytics.events;
CREATE TABLE analytics.events (
  event_id String,
  event_ts DateTime,
  user_id String,
  event_type String,
  value Float64
)
ENGINE = MergeTree
ORDER BY (event_ts, event_id);
SQL

{
  printf \"event_id,event_ts,user_id,event_type,value\\n\"
  awk -F, '
    BEGIN { OFS=\",\" }
    FNR == 1 { next }
    "'$1 == "event_id" && $2 == "event_ts" && $3 == "user_id" && $4 == "event_type" { next }
    {
      # Remove trailing empty field from files with a trailing comma.
      nf = NF
      if ($NF == "") { nf = NF - 1 }
      event_id = $1
      raw_ts = $2
      user_id = $3
      event_type = $4
      raw_value = (nf >= 5 ? $5 : "")

      if (raw_ts ~ /''^[0-9]{2}'"\\/[0-9]{2}\\/[0-9]{4}"'$/) {
        split(raw_ts, d, "/")
        event_ts = d[3] "-" d[2] "-" d[1] " 00:00:00"
      } else {
        gsub(/T/, " ", raw_ts)
        sub(/Z$/, "", raw_ts)
        event_ts = raw_ts
      }

      if (raw_value == "" || raw_value == "N/A" || raw_value == "null") {
        raw_value = "0"
      }

      print event_id, event_ts, user_id, event_type, raw_value
    }
  '"' /data/csv/events_01.csv /data/csv/events_02.csv /data/csv/events_03.csv /data/csv/events_04.csv /data/csv/events_05.csv
} > /tmp/events_normalized.csv

clickhouse-client --query \"INSERT INTO analytics.events FORMAT CSVWithNames\" < /tmp/events_normalized.csv

printf \"Normalized preview:\\n\"
sed -n \"1,10p\" /tmp/events_normalized.csv

printf \"\\nRow count:\\n\"
clickhouse-client --query \"SELECT count() FROM analytics.events\"

printf \"\\nSample rows:\\n\"
clickhouse-client --query \"SELECT event_id, formatDateTime(event_ts, '%F %T') AS event_ts, user_id, event_type, value FROM analytics.events ORDER BY event_id FORMAT TabSeparated\"
'"

